-- The economy branch of the topic tree is the JEL classification (Journal of
-- Economic Literature, American Economic Association), so economics coverage is
-- tagged against a standard ontology instead of hand-made labels. JEL's own
-- hierarchy (letter > two-digit > three-digit code) becomes the ltree path:
-- L41 is 'economy.L.L4.L41', so 'economy.L' @> it. Leaves are the three-digit
-- codes. A JEL "General"/"Other" heading is named after its parent so a chip
-- reads on its own. Source: aeaweb.org/econlit/classificationTree.xml.
--
-- jel_code names a topic's JEL code: its own for the economy branch, the
-- nearest one for a hand-made topic outside it (business.cooperatives -> J54),
-- so every economics-related label maps onto the same ontology.
alter table public.topics
  add column jel_code text check (jel_code ~ '^[A-Z]([0-9]{1,2})?$');

on conflict (id) do update set name = excluded.name, description = excluded.description;

on conflict (id) do update
  set name = excluded.name, description = excluded.description, jel_code = excluded.jel_code;

on conflict (id) do nothing;

update public.topics t set jel_code = m.jel_code
from (values
  ('business', 'M'),
  ('business.big_tech', 'L86'),
  ('business.markets_ipos', 'G1'),
  ('business.startups_funding', 'M13'),
  ('business.work_labor', 'J2'),
  ('business.cooperatives', 'J54'),
  ('politics.government_policy', 'H'),
  ('politics.law_courts', 'K4'),
  ('politics.elections', 'D72'),
  ('politics.geopolitics_military', 'F5'),
  ('politics.competition_antitrust', 'K21')
) as m(id, jel_code)
where t.id = m.id::extensions.ltree;
